package android.app;import android.content.*;public class AlertDialog extends Dialog {public static String[] items;public static DialogInterface.OnClickListener click;public static int count; public static class Builder {public Builder(Context c){}public Builder setItems(CharSequence[] a,DialogInterface.OnClickListener l){items=new String[a.length];for(int i=0;i<a.length;i++)items[i]=a[i].toString();click=l;return this;}public AlertDialog show(){count++;return new AlertDialog();}}}
